import React, { FC } from 'react';

import { SearchOptions } from '..';

interface FilterSelectorProps {
  searchOptions: SearchOptions;
  onFilterChange: (filterType: string, value: string | number) => void;
  onSearchChange: (value: string) => void;
}

const FilterSelector: FC<FilterSelectorProps> = ({ searchOptions, onFilterChange, onSearchChange }) => {
  return (
    <label>
      {searchOptions.title}:
      <select onChange={(e) => onFilterChange(searchOptions.title.toLowerCase(), e.target.value)}>
        <option value="">Select a {searchOptions.title.toLowerCase()}</option>
        {searchOptions.options.map((option: string) => (
          <option key={option} value={option}>
            {searchOptions.title === 'Price' ? `< ${option}` : option}
          </option>
        ))}
      </select>
    </label>
  );
};

export default FilterSelector;
